import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    static void bitAdd(long[] t, int i, long x) {
        int n = t.length - 1;
        for (; i <= n; i += i & -i) t[i] += x;
    }

    static long bitSum(long[] t, int i) {
        long s = 0;
        for (; i > 0; i -= i & -i) s += t[i];
        return s;
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long k = Long.parseLong(next());
        long[] a = new long[(int) n];
        for (int i = 0; i < a.length; i++) a[i] = Long.parseLong(next());

        int cnt = (int) n;
        long MOD = 1000000007L;
        long[] keys = new long[cnt];
        for (int i = 0; i < cnt; i++) keys[i] = (a[i] << 16) | i;
        Arrays.sort(keys);
        int[] rk = new int[cnt];
        int m = 0;
        long last = -1;
        for (int i = 0; i < cnt; i++) {
            long v = keys[i] >> 16;
            if (v != last) {
                m++;
                last = v;
            }
            rk[(int) (keys[i] & 65535)] = m;
        }
        long[] cur = new long[cnt];
        Arrays.fill(cur, 1);
        for (int length = 2; length <= k; length++) {
            long[] t = new long[m + 1];
            long[] nxt = new long[cnt];
            for (int i = 0; i < cnt; i++) {
                nxt[i] = bitSum(t, rk[i] - 1) % MOD;
                bitAdd(t, rk[i], cur[i]);
            }
            cur = nxt;
        }
        long total = 0;
        for (int i = 0; i < cnt; i++) total = (total + cur[i]) % MOD;
        System.out.println(total);
    }
}
